export interface Turn {
  role: "user" | "assistant";
  content: string;
  /** Когда сказано — правила записи смотрят только текущий разговор (`sessionOf`). Модели не уходит. */
  at?: Date;
  /** Написал живой сотрудник клиники, а не агент. */
  byStaff?: boolean;
}

function forModel(turn: Turn): { role: "user" | "assistant"; content: string } {
  return { role: turn.role, content: turn.byStaff ? `${STAFF_MARK} ${turn.content}` : turn.content };
}

/**
 * history — последние реплики диалога. Без неё ассистент отвечал на каждое
 * сообщение как на первое: «а сколько это стоит?» после вопроса об остеопатии
 * он уже не понимал.
 */
/**
 * Ответ вышел из роли — отправлять его пациенту нельзя.
 *
 * Живой прогон на вопросе «можно ли капельницу при беременности» вернул:
 * «I'm Claude, an AI assistant made by Anthropic. I can't provide medical
 * advice…». Всё по делу — но по-английски и от чужого имени: пациент клиники
 * получил бы сообщение на незнакомом языке, узнал бы, что говорит с моделью, и
 * остался бы без ответа. Модель срывается в собственную защитную формулировку
 * непредсказуемо, и полагаться на просьбы в промпте здесь нельзя.
 *
 * Такой ответ считается несостоявшимся: агент промолчит и позовёт человека —
 * ровно то, что и требуется на медицинском вопросе (§6).
 */
/**
 * Срезать пересказ инструкций перед ответом.
 *
 * Модель приписывает к ответу абзац о самой себе: «Acknowledged. Я —
 * справочная служба клиники, отвечаю на «вы», опираюсь только на справку…».
 * Иногда по-английски и с рассуждением о роли. Пациент получает это в
 * мессенджере первым, а настоящий ответ — вторым абзацем, если тот вообще
 * поместился в лимит.
 *
 * Просьбами в промпте это не лечится: на «не подтверждай получение правил»
 * модель отвечает «Принято» — то есть подтверждает. Поэтому режем на выходе,
 * детерминированно: это единственный способ гарантировать, что пациент
 * пересказ не увидит.
 *
 * Режем ТОЛЬКО когда есть что оставить: последний абзац из одного «Принято»
 * не абзац-преамбула, а весь ответ, и выбрасывать его нельзя.
 */
/**
 * Границы слова здесь — через отсутствие соседней буквы, а не `\b`.
 *
 * `\b` в JavaScript опирается на латинский `\w` и рядом с кириллицей не
 * находит границ вовсе: `/принято\b/` не совпадает со строкой «Принято.»
 * никогда. Правило выглядит рабочим и молча не срабатывает — ровно на этом
 * уже обжигался код агента, для чего и заведён `lib/agent/word-boundary.ts`.
 */
/**
 * Приписка о себе — узнаётся по разговору о правилах и о роли, а не по
 * вежливому началу.
 *
 * «Хорошо, записал ваши данные» начинается так же, как «Хорошо. Я справочная
 * служба…», и выбросить первый абзац значило бы потерять сам ответ. Поэтому
 * голое подтверждение отрезается, только если оно короткое и ничего не несёт.
 */
const META_MARKERS = [
  /**
   * Представление собой. Ищется в любом месте абзаца, а не только в начале:
   * модель начинает с «Acknowledged.» и представляется вторым предложением.
   */
  /(я|i)\s*[—–-]?\s*(справочная служба|am the|'m the|am an|'m an)/iu,
  /я\s+справочная\s+служба/iu,
  /(системн\p{L}+ сообщени|system message|в роли|fictional character|ai assistant)/iu,
  /^(начинаю отвечать|отвечаю на ваш вопрос|готов[аы]? помочь)(?!\p{L})/iu,
];

/** Метка, после которой начинается сам ответ. */
const ANSWER_ANCHOR = /ОТВЕТ\s*:/iu;

/**
 * Обрезать по последнему законченному предложению.
 *
 * Если законченного предложения нет вовсе (ответ короче одного), возвращаем
 * как есть: обрывок хуже целого, но пустота хуже обрывка.
 */
export function trimToSentence(text: string): string {
  const cut = Math.max(text.lastIndexOf("."), text.lastIndexOf("!"), text.lastIndexOf("?"));
  return cut > 40 ? text.slice(0, cut + 1).trim() : text;
}

export function stripPreamble(raw: string): string {
  // Пометку реплик сотрудника модель могла повторить — пациенту она не нужна.
  const text = raw.split(STAFF_MARK).join("").replace(/[ \t]{2,}/g, " ");
  /**
   * Метка — главный способ: всё до неё отрезается целиком, что бы там ни
   * было. Берём последнюю: модель иногда упоминает метку и в рассуждении.
   */
  let body = text;
  if (ANSWER_ANCHOR.test(text)) {
    const chunks = text.split(ANSWER_ANCHOR);
    const tail = chunks[chunks.length - 1].trim();
    /**
     * Метка нашлась — но разбор абзацев на этом не заканчивается.
     *
     * Модель ставит представление о себе и ПОСЛЕ метки: «ОТВЕТ: я справочная
     * служба клиники… \n\n По вашему вопросу: …». Возвращая хвост как есть,
     * мы отдавали пациенту ровно ту приписку, ради которой метка и заводилась.
     */
    if (tail.length > 0) {
      body = tail;
    } else {
      /**
       * Метка есть, а текста после неё нет: модель поставила её в конце. Ответ
       * стоит до метки — саму метку убираем, иначе пациент получит «ОТВЕТ:»
       * последней строкой.
       */
      body = chunks.slice(0, -1).join(" ").trim();
    }
  }

  const parts = body.split(/\n{2,}/).map((p) => p.trim()).filter(Boolean);
  // Возвращаем `body`, а не исходный текст: иначе отрезанное меткой вернулось бы
  // обратно, стоило ответу оказаться в один абзац.
  if (parts.length < 2) return body.trim();

  /** Короткое подтверждение без содержания: «Принято.», «Acknowledged.». */
  const bareAck = (p: string) =>
    /^(acknowledged|understood|got it|принято|понял[аи]?|подтверждаю|хорошо|готов[аы]?)(?!\p{L})/iu.test(p) &&
    p.split(/\s+/).length <= 3;

  let i = 0;
  while (i < parts.length - 1 && (META_MARKERS.some((re) => re.test(parts[i])) || bareAck(parts[i]))) {
    i += 1;
  }
  return parts.slice(i).join("\n\n");
}

export function offCharacter(text: string): boolean {
  if (!text.trim()) return true;
  /** Представился моделью или поставщиком — это не наша справочная служба. */
  if (/(anthropic|openai|chatgpt|я\s+—?\s?claude|i'?m\s+claude|language model|ai assistant)/i.test(text)) {
    return true;
  }
  /**
   * Язык определяем по доле кириллицы среди букв. Отдельные латинские слова
   * в русском ответе законны («IV-терапия», «BRAINBI»), поэтому порог мягкий:
   * решает перевес, а не наличие.
   */
  const letters = text.match(/\p{L}/gu) ?? [];
  if (letters.length < 12) return false;
  const cyrillic = letters.filter((c) => /[Ѐ-ӿ]/.test(c)).length;
  return cyrillic / letters.length < 0.5;
}

export async function answerLLM(
  question: string,
  clinicContext: string,
  history: Turn[] = [],
  /**
   * Инструкция клиники из настроек. Дописывается к базовым правилам, а не
   * заменяет их: не обещать запись, не выдумывать цены и не лезть в медицину
   * агент обязан независимо от того, что клиника напишет в своём тексте (§6).
   */
  extraRules?: string,
  /**
   * Имя собеседника. Передаём отдельно, а не надеемся, что модель найдёт его в
   * переписке: в промпт уходят последние реплики, и представившийся пациент
   * через десяток сообщений становится безымянным. Только имя — ни диагнозов,
   * ни остальных данных (§7).
   */
  patientName?: string | null,
  /**
   * Куда писать журнал попыток. Не передан — журнал не ведётся (так вызывают
   * из тестов и разовых скриптов), ответ от этого не меняется.
   */
  log?: { companyId: string; conversationId: string },
): Promise<string | null> {
  const key = process.env.ROUTER_AI;
  if (!key) {
    /**
     * Без ключа ассистент не отвечает вообще: каждый вопрос уходит человеку, и
     * со стороны это выглядит как «бот сломался». Именно так и случилось после
     * переезда на сервер — в окружении осталось пустое значение из образца.
     * Пишем в журнал при каждом обращении: молчать об этом нельзя.
     */
    console.error("[agent] не задан ROUTER_AI — ассистент не может отвечать, всё уходит человеку");
    return null;
  }

  /**
   * Одна повторная попытка на обрыв и таймаут.
   *
   * Молчание агента — самый заметный для клиники сбой: пациенту приходится
   * писать дважды, а администратор видит бота, который «иногда не отвечает».
   * Причина у этого одна и та же — единичный таймаут или оборванное
   * соединение к провайдеру модели. Вторая попытка снимает почти все такие
   * случаи и стоит секунд, а не денег: на ошибку ответа (4xx, 5xx с телом)
   * повтора нет — там дело не во времени, и второй заход даст ту же ошибку.
   *
   * Вебхуку это не мешает: провайдеру мессенджера мы отвечаем сразу, а разговор
   * ведём после ответа.
   */
  /**
   * Каждая попытка — строка в журнале, включая повтор. Иначе «модель ответила
   * со второго раза» неотличимо от «ответила сразу», а именно эта разница и
   * объясняет, почему пациенту иногда приходится ждать вдвое дольше.
   */
  let previousRun: string | null = null;
  for (let attempt = 1; attempt <= 2; attempt += 1) {
    const runId: string | null = log
      ? await startAgentRun({ ...log, model: MODEL, retryOf: previousRun })
      : null;
    const attemptResult = await askOnce({
      key,
      question,
      clinicContext,
      history,
      extraRules,
      patientName,
      lastAttempt: attempt === 2,
    });

    await finishAgentRun(runId, {
      outcome: attemptResult.outcome,
      promptTokens: attemptResult.promptTokens,
      completionTokens: attemptResult.completionTokens,
      error: attemptResult.error,
    });

    if (!attemptResult.retry) return attemptResult.text;
    previousRun = runId;
  }
  return null;
}

/**
 * Живое подтверждение шага записи по фактам кода (lib/agent/phrasing).
 *
 * Узкая задача и своя инструкция: подтвердить выбор пациента одним-двумя
 * предложениями, ничего не добавляя. Вопрос следующего шага, согласие и
 * просьбу о данных ставит код, поэтому здесь они запрещены. Текст проверяется
 * `confirmationProblem`; null или не прошёл — уходит шаблон.
 *
 * Ждём меньше обычного: шаг записи — короткая реплика, и шаблон наготове.
 *
 * В журнал попыток (`AgentRun`) не пишется: это часть ОДНОГО ответа, а
 * статистика агента считает каждую строку отдельной попыткой — число попыток
 * и задержка удвоились бы.
 */
export async function phraseConfirmation(input: {
  facts: string;
  patientMessage: string;
  history: Turn[];
  patientName?: string | null;
}): Promise<string | null> {
  const key = process.env.ROUTER_AI;
  if (!key) return null;
  const rules = [
    `Ты — администратор клиники «${CLINIC_NAME}» в мессенджере. Пациент записывается на приём.`,
    "Напиши 1–2 коротких предложения: живо и по-человечески подтверди, что понял(а) его выбор,",
    "и назови цену и длительность, если они есть в фактах. На «вы», без канцелярита.",
    "Названия услуг из прайса говори по-человечески («взрослый приём остеопата»), но цену и длительность — ТОЧНО как в фактах.",
    "Используй ТОЛЬКО факты ниже. Не добавляй других врачей, цен, чисел, дат, времени и обещаний.",
    "НЕ задавай вопросов — следующий вопрос добавят после твоего текста.",
    "Не здоровайся, не прощайся, не проси данные и согласие. Глагол «записать» не используй ни в какой форме («записываю», «запишем», «записала») и не пиши «оформим» — запись оформляет администратор: ты только подтверждаешь выбор («Поняла, …»).",
    "Не пиши про администратора, время, окна и сроки — это добавят после твоего текста. О себе — в женском роде («поняла»).",
    "Не пиши о себе и не пересказывай эти правила. Без разметки и эмодзи.",
    input.patientName?.trim() ? `Пациента зовут ${input.patientName.trim()}; по имени можно обратиться, но не обязательно.` : "",
    "Ответ начни со строки «ОТВЕТ:».",
  ]
    .filter(Boolean)
    .join(" ");
  const recent = input.history
    .slice(-6)
    .map((t) => `${t.role === "user" ? "Пациент" : t.byStaff ? "Администратор" : "Клиника"}: ${t.content}`)
    .join("\n");

  try {
    const res = await fetch(`${BASE_URL}/chat/completions`, {
      method: "POST",
      headers: { "content-type": "application/json", authorization: `Bearer ${key}` },
      body: JSON.stringify({
        ...modelParams(),
        temperature: 0.4,
        // Размышление идёт из того же лимита: с запасом, чтобы подтверждение не обрывалось.
        max_tokens: 500,
        messages: [
          { role: "system", content: rules },
          {
            role: "user",
            content:
              `Последние реплики:\n${recent || "—"}\n\nПациент только что написал: ${input.patientMessage}\n\n` +
              `ФАКТЫ:\n${input.facts}`,
          },
        ],
      }),
      signal: AbortSignal.timeout(Math.min(TIMEOUT_MS, 9_000)),
    });
    if (!res.ok) {
      console.warn(`[agent] подтверждение шага: RouterAI ${res.status}`);
      return null;
    }
    const json = (await res.json()) as {
      choices?: { message?: { content?: string }; finish_reason?: string }[];
    };
    const choice = json.choices?.[0];
    let text = stripPreamble(toPlainText(choice?.message?.content?.trim() ?? ""));
    if (text && choice?.finish_reason === "length") text = trimToSentence(text);
    if (!text || offCharacter(text)) return null;
    return text;
  } catch (e) {
    console.warn(`[agent] подтверждение шага: ${(e as Error)?.name ?? "ошибка"}`);
    return null;
  }
}

/**
 * Пересказать пациенту ответ врача.
 *
 * Отдельный вызов, а не общий `answerLLM`: там базовый промпт запрещает
 * обсуждать симптомы и лечение, и на ответ врача про головные боли модель
 * ответила бы отказом. Здесь задача другая и узкая — переложить чужие слова на
 * человеческий язык, ничего не добавив.
 *
 * Смысл не меняется ни на грамм: числа и показания сверяются с текстом врача
 * кодом (lib/agent/grounding, lib/agent/indications), и при любом расхождении
 * пациенту уходит её текст дословно. Красивее — не важнее, чем верно.
 */
export async function relayDoctorAnswer(input: {
  question: string;
  doctorAnswer: string;
  doctorName: string;
  patientName?: string | null;
}): Promise<string | null> {
  const key = process.env.ROUTER_AI;
  if (!key) return null;

  const rules = [
    `Ты — администратор клиники «${CLINIC_NAME}» в мессенджере.`,
    `Врач ${input.doctorName} ответила на вопрос пациента. Передай её ответ пациенту.`,
    "Твоя задача — только переложить её слова на человеческий язык, обращаясь на «вы».",
    "НИЧЕГО не добавляй: ни причин, ни показаний, ни сроков, ни чисел, которых нет в её ответе.",
    "Ничего не убирай по смыслу и не смягчай: если врач сказала «нельзя», так и передай.",
    "Не ставь диагнозов и не делай выводов от себя. Ты не врач, ты передаёшь ответ.",
    "Не пиши «врач сказала, что...» — просто передай ответ, начав со слов о том, что ты уточнила.",
    "Не обещай запись, время и свободные окна: этим занимается администратор.",
    "Не используй разметку. Обычный текст, 1–4 предложения.",
    input.patientName?.trim() ? `Пациента зовут ${input.patientName.trim()}.` : "",
    "\nОтвет пациенту начни со строки «ОТВЕТ:». Всё, что напишешь до неё, пациент не увидит.",
  ]
    .filter(Boolean)
    .join(" ");

  try {
    const res = await fetch(`${BASE_URL}/chat/completions`, {
      method: "POST",
      headers: { "content-type": "application/json", authorization: `Bearer ${key}` },
      body: JSON.stringify({
        ...modelParams(),
        temperature: 0.2,
        max_tokens: 900,
        messages: [
          { role: "system", content: rules },
          {
            role: "user",
            content: `Вопрос пациента:\n${input.question}\n\nОтвет врача:\n${input.doctorAnswer}`,
          },
        ],
      }),
      signal: AbortSignal.timeout(TIMEOUT_MS),
    });
    if (!res.ok) {
      console.error(`[specialist] пересказ не получился: RouterAI ${res.status}`);
      return null;
    }
    const json = (await res.json()) as {
      choices?: { message?: { content?: string }; finish_reason?: string }[];
    };
    const choice = json.choices?.[0];
    let text = stripPreamble(toPlainText(choice?.message?.content?.trim() ?? ""));
    if (text && choice?.finish_reason === "length") text = trimToSentence(text);
    if (!text || offCharacter(text)) return null;
    return text;
  } catch (e) {
    console.error("[specialist] пересказ не получился:", (e as Error)?.message ?? e);
    return null;
  }
}

/**
 * Чем кончилась одна попытка.
 *
 * Возвращаем объектом, а не строкой: журналу нужны причина, расход токенов и
 * признак «можно повторить». Держать это в переменных модуля нельзя — агент
 * отвечает нескольким пациентам одновременно, и такие переменные перепутали бы
 * их между собой.
 */
interface Attempt {
  text: string | null;
  outcome: AgentRunOutcome;
  /** Сорвалось по времени или связи — имеет смысл повторить. */
  retry: boolean;
  error?: unknown;
  promptTokens?: number | null;
  completionTokens?: number | null;
}

async function askOnce(input: {
  key: string;
  question: string;
  clinicContext: string;
  history: Turn[];
  extraRules?: string;
  patientName?: string | null;
  lastAttempt: boolean;
}): Promise<Attempt> {
  const { key, question, clinicContext, history, extraRules, patientName } = input;
  try {
    const res = await fetch(`${BASE_URL}/chat/completions`, {
      method: "POST",
      headers: { "content-type": "application/json", authorization: `Bearer ${key}` },
      body: JSON.stringify({
        ...modelParams(),
        temperature: 0.3,
        /**
         * Запас на преамбулу.
         *
         * Четырёхсот не хватало: модель тратила их на пересказ собственных
         * правил, и настоящий ответ обрывался на полуслове — «Работаем с
         * понедельника по субботу с 09:00 до 21:00. Вос». Оборванный ответ
         * уходит пациенту как есть, и это хуже длинного.
         */
        /**
         * Запас с учётом преамбулы.
         *
         * Модель тратит часть лимита на пересказ собственных правил ПЕРЕД
         * меткой «ОТВЕТ:» — мы его отрезаем, но заплачено за него уже из
         * этого бюджета. Семисот не хватало: пациент получил «...и
         * доступности запис» — оборванное на полуслове объяснение про цены
         * двух врачей.
         */
        max_tokens: 1200,
        messages: [
          /**
           * Все указания — ОДНИМ системным сообщением.
           *
           * Их было четыре подряд, и модель отвечала на последнее из них, а не
           * пациенту: ответ начинался с «Acknowledged. Я — справочная служба…»
           * и пересказа собственных правил. Пациент получал это в мессенджере,
           * а настоящий ответ либо шёл следом, либо обрывался на полуслове —
           * пересказ съедал лимит ответа. Проверено живыми прогонами:
           * `scripts/agent-live-test.ts`.
           */
          {
            role: "system",
            content: [
              PATIENT_PROMPT,
              extraRules?.trim() ? `\nИнструкция клиники:\n${extraRules.trim()}` : "",
              patientName?.trim()
                ? `\nСобеседника зовут ${patientName.trim()}. Обращайтесь по имени.`
                : "",
              `\nСправка клиники:\n${clinicContext}`,
              /**
               * Якорь ответа.
               *
               * Просить «не пиши преамбулу» бесполезно: модель приписывает
               * абзац о себе всё равно, а на «не подтверждай получение
               * правил» отвечает «Принято». Зато формат вывода она держит
               * надёжно. Поэтому пациенту уходит только то, что стоит после
               * метки, а всё до неё отрезается — что бы там ни оказалось.
               */
              "\nОтвет пациенту начни со строки «ОТВЕТ:». Всё, что напишешь до неё, пациент не увидит.",
            ]
              .filter(Boolean)
              .join("\n"),
          },
          // Последние реплики — чтобы «а сколько это стоит?» понималось в контексте.
          /**
           * Двадцать реплик, а не десять: на десяти пациент, назвавший себя в
           * начале разговора, к середине становился незнакомым — и агент честно
           * отвечал, что имени не знает.
           */
          ...history.slice(-20).map(forModel),
          { role: "user", content: question },
        ],
      }),
      // Вебхук должен уложиться в срок ожидания мессенджера, иначе он
      // пришлёт сообщение повторно и пациент получит два ответа.
      signal: AbortSignal.timeout(TIMEOUT_MS),
    });

    if (!res.ok) {
      /**
       * Причину видно в журнале сервера. Раньше отказ молча превращался в
       * null, и на экране это выглядело как «ассистент вдруг перестал
       * отвечать» — ровно так же, как когда-то молчали push-уведомления.
       */
      const body = await res.text().catch(() => "");
      console.error(`[agent] модель ответила ${res.status}: ${body.slice(0, 200)}`);
      // Ошибка ответа — не про время: повтор даст ту же ошибку.
      return {
        text: null,
        outcome: "PROVIDER_ERROR",
        retry: false,
        error: `RouterAI ${res.status}`,
      };
    }

    const json = (await res.json()) as {
      choices?: { message?: { content?: string }; finish_reason?: string }[];
      usage?: { prompt_tokens?: number; completion_tokens?: number };
    };
    const choice = json.choices?.[0];
    /**
     * Разметку снимаем на выходе.
     *
     * В промпте про неё сказано, но модель соблюдает просьбы через раз, а
     * ответ уходит пациенту каждый раз. Инструкция клиники теперь тоже
     * приходит из настроек и бывает написана в markdown — модель охотно
     * повторяет её оформление, и в WhatsApp приезжает «**Стоимость**».
     */
    let text = stripPreamble(toPlainText(choice?.message?.content?.trim() ?? ""));

    /**
     * Ответ упёрся в лимит — обрезаем по последнему законченному предложению.
     *
     * Оборванное на полуслове сообщение уходит ПАЦИЕНТУ. Он видит «...и
     * доступности запис» и не понимает, дописал бот или пропала связь. Лучше
     * короче, но целиком: недосказанная мысль в мессенджере читается как
     * поломка, а поломке пациент не доверяет.
     */
    if (text && choice?.finish_reason === "length") {
      const trimmed = trimToSentence(text);
      console.error(
        `[agent] ответ упёрся в лимит, обрезан по предложению: было ${text.length} знаков, стало ${trimmed.length}`,
      );
      text = trimmed;
    }

    if (text && offCharacter(text)) {
      console.error("[agent] ответ вне роли — не отправляем пациенту, зовём человека");
      return {
        text: null,
        outcome: "EMPTY_RESPONSE",
        // Повтор не поможет: модель сорвалась на самом вопросе, а не на связи.
        retry: false,
        error: "ответ вне роли",
        promptTokens: json.usage?.prompt_tokens ?? null,
        completionTokens: json.usage?.completion_tokens ?? null,
      };
    }
    const promptTokens = json.usage?.prompt_tokens ?? null;
    const completionTokens = json.usage?.completion_tokens ?? null;
    if (!text) {
      console.error(
        `[agent] модель вернула пустой ответ (finish_reason: ${choice?.finish_reason ?? "нет"}), ` +
          `длина справки ${clinicContext.length} знаков`,
      );
      return {
        text: null,
        outcome: "EMPTY_RESPONSE",
        retry: false,
        error: `пустой ответ, finish_reason: ${choice?.finish_reason ?? "нет"}`,
        promptTokens,
        completionTokens,
      };
    }
    return { text, outcome: "OK", retry: false, promptTokens, completionTokens };
  } catch (e) {
    const name = (e as Error)?.name;
    const timeout = name === "TimeoutError";
    console.error(
      timeout
        ? `[agent] модель не ответила за ${TIMEOUT_MS} мс, длина справки ${clinicContext.length} знаков` +
            (input.lastAttempt ? "" : " — повторяю")
        : `[agent] сбой обращения к модели: ${String((e as Error)?.message ?? e).slice(0, 200)}` +
            (input.lastAttempt ? "" : " — повторяю"),
    );
    return {
      text: null,
      outcome: timeout ? "TIMEOUT" : "PROVIDER_ERROR",
      // Повторяем только то, что могло сорваться случайно.
      retry: !input.lastAttempt,
      error: timeout ? `таймаут ${TIMEOUT_MS} мс` : `сбой связи: ${name ?? "неизвестно"}`,
    };
  }
}
